    agregar("G07-L2-04", CLASE_7, "L2", "El electroventilador no arranca ni cuando el tablero marca 100 grados; solo se activa si enciendo el botón del aire acondicionado.", "TALLER", "ralenti_caliente", "ventilador_no_enciende_por_temperatura|enciende_forzado_ac", "falla_motor_ventilador", "", "NO", "NO", "", "L2 falla en relay/sensor de ventilador.")
    agregar("G07-L2-05", CLASE_7, "L2", "Hola, mi carro calienta parado pero el nivel de refrigerante está completo y el aceite está limpio sin nada de mayonesa.", "WHATSAPP", "parado", "calienta_parado", "perdida_refrigerante|emulsion_aceite", "", "NO", "SI", CLASE_6, "L2 descarta culata por ausencia de emulsión y nivel OK.")
    agregar("G07-L2-06", CLASE_7, "L2", "Al quedarme embotellado en cola sube la aguja; abro el capó y veo que el aspa del ventilador está totalmente quieta.", "COTIDIANO", "embotellamiento", "temperatura_sube_cola|ventilador_detenido", "fuga_liquido", "", "NO", "SI", CLASE_8, "L2 visual de ventilador detenido sin fugas.")
    agregar("G07-L2-07", CLASE_7, "L2", "El carro se calienta a los cinco minutos de encendido en plano y sin forzarlo. El agua no circula hacia el panel del radiador.", "TALLER", "plano_sin_carga", "calentamiento_rapido_sin_carga|no_circula_radiador", "fuga_refrigerante", "", "NO", "SI", CLASE_8, "L2 falta de circulación por termostato vs fuga.")
    agregar("G07-L2-08", CLASE_7, "L2", "La calefacción no calienta en carretera y el tablero me arroja código P0128 indicando que el motor no llega a su temperatura de servicio.", "TECNICO", "carretera", "calefaccion_fria|motor_frio_carretera", "sobrecalentamiento", "P0128", "NO", "NO", "", "L2 termostato abierto DTC P0128.")
    agregar("G07-L2-09", CLASE_7, "L2", "El motoventilador vibra horrible y hace un chillido fuerte de buje gastado girando a muy pocas revoluciones en caliente.", "COTIDIANO", "motor_caliente", "chillido_ventilador|baja_velocidad_aspa", "rotura_faja", "", "NO", "NO", "", "L2 desgaste mecánico en motor del ventilador.")
    agregar("G07-L2-10", CLASE_7, "L2", "Se calienta solo al parar en los semaforos despues de rodar media hora. Al andar normal a 60 no calienta nada.", "ERROR_ORTOGRAFICO", "parada_semaforo", "calienta_en_parada", "calienta_a_velocidad", "", "NO", "SI", CLASE_6, "L2 calentamiento exclusivo en detención con ortografía informal.")
    agregar("G07-L2-11", CLASE_7, "L2", "Buenas, el carro calienta cuando estoy en cola y si prendo el aire acondicionado se recalienta mucho más rápido.", "WHATSAPP", "cola_con_ac", "recalienta_en_cola|empeora_con_ac", "humo_blanco", "", "NO", "SI", CLASE_6, "L2 sobrecarga de condensador por ventilador defectuoso.")
    agregar("G07-L2-12", CLASE_7, "L2", "El radiador se mantiene tibio mientras el motor está hirviendo; la válvula termostática parece haberse quedado pegada en su asiento.", "TALLER", "motor_caliente", "radiador_tibio|motor_hirviendo", "perdida_agua", "", "NO", "SI", CLASE_8, "L2 termostato bloqueado mecánicamente cerrado.")
    agregar("G07-L2-13", CLASE_7, "L2", "Aparece testigo Check Engine P0480 y el ventilador principal del radiador no gira al llegar el motor a 98 grados Celsius.", "TECNICO", "ralenti", "dtc_p0480|ventilador_inactivo_98c", "fuga_circuito", "P0480", "NO", "NO", "", "L2 falla de circuito ventilador P0480.")
    agregar("G07-L2-14", CLASE_7, "L2", "El carro calienta parado pero no bota agua ni tiene mangueras reventadas; el nivel se mantiene intacto en la línea de máximo.", "COTIDIANO", "parado", "calienta_parado", "fuga_manguera|baja_nivel", "", "NO", "SI", CLASE_8, "L2 nivel intacto descarta fuga externa.")
    agregar("G07-L2-15", CLASE_7, "L2", "Fusible del electroventilador se quema cada vez que el motor intenta activarlo al llegar a temperatura de régimen.", "TALLER", "activacion_ventilador", "fusible_ventilador_quemado|ventilador_en_corto", "falla_bomba", "", "NO", "NO", "", "L2 cortocircuito en devanado de ventilador.")

    # --- L3 (15 casos) ---
    agregar("G07-L3-01", CLASE_7, "L3", "Temperatura alcanza 108 grados únicamente en ralentí tras 10 minutos de detención. Al escanear con equipo en vivo el sensor ECT marca 106°C pero el comando de baja velocidad del ventilador no energiza el motor eléctrico. El nivel de refrigerante está completo y al rodar a 60 km/h la temperatura cae a 90°C.", "TECNICO", "ralenti_prolongado", "temperatura_108_ralenti|ect_106_sin_ventilador|cae_a_90_en_marcha", "perdida_refrigerante", "P0480", "NO", "SI", CLASE_6, "L3 comando de ventilador inoperante en escáner.")
    agregar("G07-L3-02", CLASE_7, "L3", "El motor recalienta a los 5 kilómetros de recorrido tanto en ciudad como en carretera. Termómetro infrarrojo registra 105°C en la manguera superior y 38°C en la manguera inferior. No hay fugas y el líquido no tiene restos de hidrocarburos ni burbujas.", "TALLER", "marcha_corta", "manguera_sup_105c_inf_38c|recalentamiento_ambas_condiciones", "hidrocarburos_refrigerante|fugas", "", "NO", "SI", CLASE_6, "L3 gradiente térmico 105°C vs 38°C descarta culata.")
    agregar("G07-L3-03", CLASE_7, "L3", "Escáner registra código P0128 permanente. El vehículo circula en carretera a 100 km/h y la temperatura del refrigerante no supera los 65°C. La calefacción emite aire templado y el ajuste de combustible a largo plazo se enriqueció un 12%. El termostato quedó trabado abierto en su carcasa.", "TECNICO", "carretera_100kmh", "dtc_p0128|ect_65c_en_ruta|ltft_enriquecido", "sobrecalentamiento", "P0128", "NO", "NO", "", "L3 termostato trabado abierto con telemetría de trim.")
    agregar("G07-L3-04", CLASE_7, "L3", "En tráfico pesado la aguja roza la zona roja. Al revisar en taller el motor del electroventilador presenta resistencia infinita en su conector por escobillas desgastadas. Se puenteó el relé directo y no giró. El empaque de culata se probó sin fugas de compresión.", "TALLER", "trafico_pesado", "electroventilador_resistencia_infinita|escobillas_gastadas", "fuga_compresion_culata", "", "NO", "SI", CLASE_6, "L3 comprobación eléctrica de motor de ventilador vs culata.")
    agregar("G07-L3-05", CLASE_7, "L3", "Hola, mi carro calienta en los semáforos pero si salgo a la Vía Expresa a 70 km/h la aguja se clava al medio exacto. El nivel de agua no baja nada, no hay humo blanco y el ventilador no arranca por su cuenta.", "WHATSAPP", "via_rapida_vs_semaforo", "calienta_semaforo|enfria_via_rapida", "baja_nivel_agua|humo_blanco", "", "NO", "SI", CLASE_6, "L3 flujo de aire dinámico enfría radiador.")
    agregar("G07-L3-06", CLASE_7, "L3", "Sobrecalentamiento súbito a 112°C. El radiador está frío al tacto en la mitad inferior. Al desmontar la toma de agua se encontró el resorte del termostato roto y el émbolo cruzado en posición totalmente cerrada sin daño en la junta de culata.", "TALLER", "despues_de_recalentar", "termostato_embolo_cruzado_cerrado|radiador_frio_inferior", "dano_junta_culata", "P0217", "NO", "SI", CLASE_6, "L3 inspección física del resorte de termostato.")
    agregar("G07-L3-07", CLASE_7, "L3", "Código P0480 almacenado en ECU. Al realizar prueba de actuadores con el escáner el relé del ventilador de baja velocidad conmuta con clic audible pero no hay salida de 12 voltios hacia el motor por resistencia en el cableado. En carretera la temperatura es de 88°C estable.", "TECNICO", "prueba_actuadores", "dtc_p0480|rele_clic_sin_12v|88c_en_carretera", "falla_termostato", "P0480", "NO", "NO", "", "L3 diagnóstico de caída de voltaje en arnés de ventilador.")
    agregar("G07-L3-08", CLASE_7, "L3", "El vehículo calienta en tráfico congestionado pero el refrigerante está en nivel máximo y no hay burbujeo en el vaso de expansión. Al aplicar corriente directa de 12V a la ficha del electroventilador este no gira y consume 0 amperios por circuito abierto interno.", "TALLER", "trafico_congestionado", "ventilador_consumo_0_amperios|circuito_abierto", "burbujeo_vaso_expansion|perdida_liquido", "", "NO", "SI", CLASE_6, "L3 prueba de corriente directa en ventilador.")
    agregar("G07-L3-09", CLASE_7, "L3", "El auto demora 40 minutos en alcanzar 80 grados y al rodar en bajada la aguja desciende a un cuarto. Termostato retirado para comprobación en banco no cierra herméticamente dejando pasar luz entre el sello y el cuerpo a temperatura ambiente.", "TALLER", "prueba_banco", "termostato_no_cierra_hermetico|demora_calentar", "sobrecalentamiento", "P0128", "NO", "NO", "", "L3 prueba visual de cierre de termostato en frío.")
    agregar("G07-L3-10", CLASE_7, "L3", "El motor recalienta al parar en el semaforo. Mangueras en perfecto estado sin roturas ni fugas, nivel en el maximo, pero el ventilador no gira porque el modulo de control de ventilador esta quemado. En pista libre a 80 km/h la temperatura baja normal.", "ERROR_ORTOGRAFICO", "parada_y_pista_libre", "modulo_ventilador_quemado|temperatura_baja_80kmh", "mangueras_rotas|fugas_refrigerante", "", "NO", "SI", CLASE_8, "L3 módulo de ventilador quemado con mangueras sanas.")
    agregar("G07-L3-11", CLASE_7, "L3", "La temperatura sube en ralentí hasta que salta la alarma acústica a 105°C. El electroventilador solo prende en velocidad alta cuando la presión de alta del gas refrigerante del aire acondicionado supera los 220 psi, pero no activa por la señal del sensor de temperatura de motor.", "TECNICO", "ralenti_con_ac", "electro_no_activa_por_ect|solo_activa_por_presion_ac", "fuga_refrigerante_motor", "", "NO", "NO", "", "L3 activación por presostato de A/C pero no por ECT.")
    agregar("G07-L3-12", CLASE_7, "L3", "El motor calienta en ralentí y ciudad pero el aceite está en óptimo estado y no hay sobrepresión de gases en el radiador. El relé del motoventilador presentó patillas sulfatadas con caída de tensión de 4 voltios bajo carga impidiendo el giro normal del aspa.", "TALLER", "ciudad_ralenti", "rele_sulfatado_caida_4v|aspa_no_gira", "emulsion_aceite|sobrepresion_gases", "", "NO", "SI", CLASE_6, "L3 caída de tensión en relé descarta culata.")
    agregar("G07-L3-13", CLASE_7, "L3", "Recalentamiento rápido en menos de 3 km. Ambas mangueras sin fugas de líquido. La manguera superior se encuentra a 102°C y el radiador permanece templado a 45°C. El termostato se probó en agua caliente en taller y no abrió a los 88°C especificados.", "TALLER", "prueba_banco_termostato", "termostato_no_abre_a_88c|manguera_102c_radiador_45c", "fuga_liquido_mangueras", "P0217", "NO", "SI", CLASE_8, "L3 ensayo en agua caliente de termostato trabado.")
    agregar("G07-L3-14", CLASE_7, "L3", "En autopista despejada a 110 km/h la temperatura se desploma a 60 grados encendiendo el check con DTC P0128. En ralentí en garaje sube a 85 grados lentamente. El termostato instalado carece de empaque de borde y permanece abierto.", "TECNICO", "autopista_despejada", "dtc_p0128|desplome_temperatura_60c", "calentamiento_en_autopista", "P0128", "NO", "NO", "", "L3 termostato con sello roto o abierto en crucero.")
    agregar("G07-L3-15", CLASE_7, "L3", "Maestro, mi carro calienta feo en las colas de la avenida pero saliendo a pista libre no calienta nada. Ya miré el aceite y está doradito, no le falta agua y el ventilador está parado sin moverse cuando la aguja ya pasó la mitad.", "WHATSAPP", "cola_urbana", "calienta_en_cola|ventilador_parado", "aceite_chocolatoso|falta_agua", "", "NO", "SI", CLASE_6, "L3 descripción coloquial WhatsApp descarta culata y fuga.")

    # =========================================================================
