    # --- L1 (10 casos) ---
    agregar("G08-L1-01", CLASE_8, "L1", "Encontré un charco verdoso debajo del parachoques delantero.", "COTIDIANO", "reposo_garaje", "charco_verdoso_delantero", "", "", "SI", "NO", "", "L1 charco de refrigerante.")
    agregar("G08-L1-02", CLASE_8, "L1", "Cada dos días tengo que rellenar el depósito del refrigerante.", "WHATSAPP", "rutina", "relleno_frecuente_refrigerante", "", "", "SI", "NO", "", "L1 pérdida periódica de nivel.")
    agregar("G08-L1-03", CLASE_8, "L1", "Sale vapor blanco por la rejilla del radiador cuando me detengo.", "COTIDIANO", "detencion", "vapor_rejilla_radiador", "", "", "SI", "NO", "", "L1 vapor frontal por fuga caliente.")
    agregar("G08-L1-04", CLASE_8, "L1", "Huele como a dulce quemado cuando bajo del auto.", "COTIDIANO", "despues_de_manejar", "olor_dulce_quemado", "", "", "SI", "NO", "", "L1 olor dulce de etilenglicol evaporado.")
    agregar("G08-L1-05", CLASE_8, "L1", "Vi unas gotas rosadas cayendo cerca de una manguera gruesa.", "WHATSAPP", "motor_encendido", "goteo_rosado_manguera", "", "", "SI", "NO", "", "L1 goteo localizado en manguera.")
    agregar("G08-L1-06", CLASE_8, "L1", "El depósito de agua se vacía solo de un día para otro.", "COTIDIANO", "estacionado", "deposito_se_vacia", "", "", "SI", "NO", "", "L1 vaciado estático de depósito.")
    agregar("G08-L1-07", CLASE_8, "L1", "Se ve como sarro seco de color verde en la esquina del radiador.", "TALLER", "inspeccion_visual", "sarro_verde_esquina_radiador", "", "", "SI", "NO", "", "L1 sarro seco cristalizado en radiador.")
    agregar("G08-L1-08", CLASE_8, "L1", "Ayer escupió agua caliente por delante al llegar a mi casa.", "COTIDIANO", "llegada_parada", "escape_agua_caliente_frontal", "", "", "SI", "NO", "", "L1 rotura/escape frontal repentino.")
    agregar("G08-L1-09", CLASE_8, "L1", "Tengo una manguera del motor hinchada y con humedad en la abrasadera.", "ERROR_ORTOGRAFICO", "inspeccion", "manguera_hinchada_humedad", "", "", "SI", "NO", "", "L1 manguera hinchada con error ortográfico.")
    agregar("G08-L1-10", CLASE_8, "L1", "Pérdida externa de refrigerante con goteo continuo en el soporte inferior del radiador.", "TECNICO", "ralenti", "perdida_externa_goteo_inferior", "", "", "SI", "NO", "", "L1 técnico de goteo en soporte de radiador.")

    # --- L2 (15 casos) ---
    agregar("G08-L2-01", CLASE_8, "L2", "Hay un charco de líquido verde bajo el radiador cada mañana y el nivel baja dos dedos, pero el motor no calienta mientras tenga agua.", "COTIDIANO", "reposo_manana", "charco_verde_radiador|baja_nivel_dos_dedos", "sobrecalentamiento", "", "NO", "SI", CLASE_7, "L2 fuga externa con temperatura normal mientras hay fluido.")
    agregar("G08-L2-02", CLASE_8, "L2", "Se observa un hilo fino de vapor saliendo del panel del radiador y goteo constante por la unión entre el aluminio y el tanque de plástico.", "TALLER", "motor_caliente", "hilo_vapor_panel|goteo_tanque_plastico_aluminio", "falla_ventilador", "", "NO", "SI", CLASE_7, "L2 fisura en sello de tanque plástico de radiador.")
    agregar("G08-L2-03", CLASE_8, "L2", "La manguera superior del radiador tiene una pequeña grieta cerca de la abrazadera y pulveriza refrigerante caliente sobre el alternador.", "COTIDIANO", "aceleracion", "manguera_agrietada|pulverizacion_refrigerante", "humo_blanco_escape", "", "NO", "SI", CLASE_6, "L2 manguera pinchada externa vs humo de culata.")
    agregar("G08-L2-04", CLASE_8, "L2", "Goteo constante de refrigerante rojo por la parte baja del radiador al presurizar el circuito, con aceite de motor completamente limpio.", "TECNICO", "prueba_presion", "goteo_radiador_rojo", "emulsion_aceite", "", "NO", "SI", CLASE_6, "L2 goteo radiador con aceite limpio descarta culata.")
    agregar("G08-L2-05", CLASE_8, "L2", "Hola, encontré agua verde chorreando por la bandeja del motor. El carro camina bien y el ventilador sí gira cuando prende.", "WHATSAPP", "marcha", "chorreo_agua_bandeja", "falla_ventilador", "", "NO", "SI", CLASE_7, "L2 chorreo externo con ventilador funcionando OK.")
    agregar("G08-L2-06", CLASE_8, "L2", "El radiador está picado en la esquina inferior izquierda; se nota sarro blanco con verde acumulado y mancha el piso al enfriarse.", "TALLER", "enfriamiento", "radiador_picado_sarro|mancha_piso_enfriar", "humo_escape", "", "NO", "NO", "", "L2 fuga en frío por dilatación en radiador picado.")
    agregar("G08-L2-07", CLASE_8, "L2", "Manguera del calefactor que entra a la cabina está reseca y gotea sobre la caja de cambios, bajando el depósito cada tres días.", "COTIDIANO", "motor_encendido", "manguera_calefactor_gotea", "temperatura_alta", "", "NO", "NO", "", "L2 manguera de calefactor agrietada.")
    agregar("G08-L2-08", CLASE_8, "L2", "Siento fuerte olor a etilenglicol dulce al parar en peajes y veo gotas que caen al protector de cárter sin que la aguja pase del medio.", "COTIDIANO", "parada_peaje", "olor_etilenglicol|gotas_protector_carter", "temperatura_alta", "", "NO", "SI", CLASE_7, "L2 olor dulce y gotas con aguja al medio.")
    agregar("G08-L2-09", CLASE_8, "L2", "El tanque plastico del radiador tiene una rajadura fina por donde escupe un chorrito de agua caliente cuando acelero.", "ERROR_ORTOGRAFICO", "aceleracion", "tanque_radiador_rajado|chorro_agua", "burbujas_compresion", "", "NO", "SI", CLASE_6, "L2 fisura en tanque plástico con error ortográfico.")
    agregar("G08-L2-10", CLASE_8, "L2", "Caída de presión rápida en el manómetro de prueba de enfriamiento a 15 psi, detectando fuga audible en la manguera inferior del radiador.", "TECNICO", "prueba_bomba_manual", "caida_presion_15psi|fuga_manguera_inferior", "fuga_interna_cilindro", "", "NO", "SI", CLASE_6, "L2 test de presurización con fuga externa audible.")
    agregar("G08-L2-11", CLASE_8, "L2", "Buenas, gotea refrigerante por la manguera fina del retorno al tacho porque la abrazadera original cedió y está floja.", "WHATSAPP", "reposo", "goteo_manguera_retorno|abrazadera_floja", "rotura_radiador", "", "NO", "NO", "", "L2 abrazadera de retorno vencida.")
    agregar("G08-L2-12", CLASE_8, "L2", "Al apagar el motor se escucha un silbido delante y cae un chorro de agua caliente por la unión de la manguera gruesa inferior.", "COTIDIANO", "al_apagar", "silbido_frontal|chorro_manguera_inferior", "ebullicion_interna", "", "NO", "NO", "", "L2 despresurización por rotura de manguera inferior.")
    agregar("G08-L2-13", CLASE_8, "L2", "Radiador con panel corroído por usar agua de caño en vez de refrigerante; tiene microfugas que manchan de óxido y bajan el nivel.", "TALLER", "inspeccion", "radiador_corroido_oxido|microfugas_panel", "falla_empaque", "", "NO", "SI", CLASE_6, "L2 corrosión por agua común vs culata.")
    agregar("G08-L2-14", CLASE_8, "L2", "El auto pierde agua solo cuando calienta y agarra presión, dejando un charco claro debajo del parachoques sin gotear en frío.", "COTIDIANO", "motor_caliente", "fuga_bajo_presion|charco_parachoques", "fuga_estatica_frio", "", "NO", "NO", "", "L2 fuga térmica por dilatación.")
    agregar("G08-L2-15", CLASE_8, "L2", "Manguera bypass de la bomba de agua con hinchazón severa y pérdida por goteo continuo sobre la polea del cigüeñal.", "TECNICO", "ralenti", "manguera_bypass_hinchada|goteo_sobre_polea", "falla_bomba_agua", "", "NO", "NO", "", "L2 manguera bypass degradada.")

    # --- L3 (15 casos) ---
    agregar("G08-L3-01", CLASE_8, "L3", "Pérdida de un litro de refrigerante cada 200 km. Al aplicar la bomba de presurización al radiador a 15 psi con el motor apagado, la presión cae a 5 psi en 30 segundos y se observa un chorro continuo en el tanque lateral plástico del radiador fisurado.", "TECNICO", "prueba_estatica_15psi", "caida_presion_15_a_5psi|chorro_tanque_lateral_fisurado", "fuga_interna|emulsion_aceite", "", "NO", "SI", CLASE_6, "L3 prueba de presión 15 psi localiza fisura en tanque lateral.")
    agregar("G08-L3-02", CLASE_8, "L3", "El cliente reclama olor a refrigerante y charco matutino. En elevador se comprueba manguera inferior de radiador rozada por la polea de la dirección hidráulica, presentando desgaste y perforación milimétrica con fuga activa a temperatura de régimen.", "TALLER", "inspeccion_elevador", "manguera_rozada_polea|perforacion_milimetrica_fuga", "sobrecalentamiento_previo", "", "NO", "NO", "", "L3 daño mecánico por roce en manguera inferior.")
    agregar("G08-L3-03", CLASE_8, "L3", "Vapor blanco saliendo por la parrilla tras 15 minutos de manejo. El panel del radiador de aluminio presenta tres tubos picados con incrustaciones verdes y goteo constante. El aceite de motor está en nivel correcto y el electroventilador conmuta normalmente.", "TALLER", "motor_caliente", "tubos_radiador_picados|vapor_parrilla|goteo_constante", "aceite_contaminado|falla_ventilador", "", "NO", "SI", CLASE_7, "L3 tubos picados con ventilador y aceite conformes.")
    agregar("G08-L3-04", CLASE_8, "L3", "El depósito de refrigerante se vacía cada dos días. Prueba con líquido fluorescente UV reveló fuga brillante en la junta del termostato y abrazadera inferior de radiador. No hay presencia de burbujas en expansión ni hidrocarburos.", "TECNICO", "inspeccion_uv", "fuga_uv_abrazadera_radiador|perdida_refrigerante", "burbujas_expansion|hidrocarburos", "", "NO", "SI", CLASE_6, "L3 trazador UV confirma fuga externa.")
    agregar("G08-L3-05", CLASE_8, "L3", "Hola maestro, goteaba agua rosada bajo el parachoques. Desarmé la defensa y el tanque plástico superior del radiador tiene una rajadura de 10 centímetros cerca del cuello de llenado que escupe líquido con el motor caliente.", "WHATSAPP", "motor_caliente", "rajadura_10cm_tanque_superior|fuga_cuello_llenado", "humo_escape", "", "NO", "SI", CLASE_6, "L3 fisura de 10 cm en tanque superior descarta culata.")
    agregar("G08-L3-06", CLASE_8, "L3", "Al exigir el motor en subida la aguja sube porque el nivel de agua bajó a la mitad. Se constató rotura longitudinal de 2 cm en manguera de retorno de calefacción por envejecimiento de la goma, con charco evidente en el piso de la cochera.", "COTIDIANO", "subida_post_perdida", "rotura_manguera_calefaccion|charco_cochera|nivel_bajo", "falla_empaque_culata", "", "NO", "SI", CLASE_6, "L3 rotura longitudinal de manguera de calefacción.")
    agregar("G08-L3-07", CLASE_8, "L3", "Presurización del sistema a 1.2 bar con manómetro de taller. Se detecta fuga activa por microfisuras en el engrapado del radiador entre el plástico y el aluminio. La compresión de los 4 cilindros se mantiene en 175 psi parejos sin caída.", "TECNICO", "presurizacion_1_2_bar", "fuga_engrapado_radiador|compresion_175psi_pareja", "falla_compresion", "", "NO", "SI", CLASE_6, "L3 engrapado fisurado con compresión 175 psi pareja.")
    agregar("G08-L3-08", CLASE_8, "L3", "El auto botó todo el refrigerante en plena avenida. Se encontró la manguera superior abierta en forma de boca de pez por degradación térmica y química. El radiador está en buen estado y el ventilador enciende a 96°C.", "TALLER", "parada_emergencia", "manguera_superior_abierta_boca_pez|perdida_total_liquido", "dano_radiador|falla_ventilador", "", "NO", "SI", CLASE_7, "L3 rotura boca de pez con ventilador verificado.")
    agregar("G08-L3-09", CLASE_8, "L3", "Tengo una fuga en el radiador que moja la pista cada ves que estaciono. El carro no calienta en movimiento pero el tacho queda seco. El mecanico le puso bomba de aire y salio chorro de agua por el medio del panal del radiador.", "ERROR_ORTOGRAFICO", "estacionamiento", "fuga_panal_radiador|chorro_bajo_presion", "calentamiento_en_movimiento", "", "NO", "SI", CLASE_7, "L3 panal perforado con prueba de aire y error ortográfico.")
    agregar("G08-L3-10", CLASE_8, "L3", "Consumo continuo de medio litro diario de anticongelante. Radiador presenta corrosión galvánica externa con goteo por la base inferior derecha. La prueba de CO2 en gases de escape sobre refrigerante resultó negativa.", "TECNICO", "inspeccion_taller", "corrosion_galvanica_radiador|goteo_inferior_derecho", "co2_refrigerante_negativo", "", "NO", "SI", CLASE_6, "L3 corrosión externa con test CO2 negativo descarta culata.")
    agregar("G08-L3-11", CLASE_8, "L3", "Buenas, gotea líquido verde por debajo del motor al apagarlo. Mirando con linterna se ve la manguera inferior cuarteada con tres chorritos finos hacia el chasis. La temperatura nunca pasó de la mitad.", "WHATSAPP", "al_apagar", "manguera_inferior_cuarteada|chorros_hacia_chasis", "sobrecalentamiento", "", "NO", "NO", "", "L3 chorros visibles en manguera cuarteada.")
    agregar("G08-L3-12", CLASE_8, "L3", "Pérdida de refrigerante solo en frío durante la noche por contracción de la manguera superior reseca sobre la boca de aluminio del termostato. Al encender y dilatar cesa la fuga, dejando charco de 200 ml cada madrugada.", "TALLER", "reposo_nocturno_frio", "fuga_por_contraccion_nocturna|charco_200ml", "fuga_en_caliente", "", "NO", "NO", "", "L3 fuga estática por contracción térmica nocturna.")
    agregar("G08-L3-13", CLASE_8, "L3", "Vapor blanco saliendo bajo el capó al llegar de viaje. Se diagnosticó perforación en el radiador producida por impacto de piedra en carretera. El circuito perdió 1.5 litros pero el motor se apagó a tiempo sin recalentar la culata.", "COTIDIANO", "viaje_carretera", "impacto_piedra_radiador|perforacion_panel|fuga_1_5l", "dano_culata", "", "NO", "SI", CLASE_6, "L3 impacto de piedra en radiador sin daño a culata.")
    agregar("G08-L3-14", CLASE_8, "L3", "Inspección técnica: sistema no retiene 1.0 bar de presión estática. Se evidencia goteo profuso por la manguera de derivación hacia el enfriador de aceite, la cual se encuentra reblandecida por contaminación de aceite externo.", "TECNICO", "presurizacion_estatica", "goteo_manguera_enfriador_aceite|manguera_reblandecida", "dano_radiador_principal", "", "NO", "NO", "", "L3 manguera ablandada por aceite externo con pérdida activa.")
    agregar("G08-L3-15", CLASE_8, "L3", "El auto derramó dos litros de refrigerante en el garaje. La abrazadera inferior tipo resorte del radiador perdió tensión y la manguera se zafó parcialmente. El panel del radiador y el empaque de culata están en perfecto estado.", "TALLER", "garaje", "abrazadera_resorte_vencida|manguera_zafada", "dano_empaque_culata|dano_radiador", "", "NO", "SI", CLASE_6, "L3 abrazadera zafada con culata y radiador intactos.")

    # =========================================================================
    # CLASE 9: Consumo de aceite por desgaste de anillos o retenes (40 casos: 10 L1, 15 L2, 15 L3)
    # =========================================================================

    # --- L1 (10 casos) ---
    agregar("G09-L1-01", CLASE_9, "L1", "El carro me está pidiendo un litro de aceite cada dos semanas.", "COTIDIANO", "marcha", "consumo_aceite_frecuente", "", "", "SI", "NO", "", "L1 consumo elevado de aceite.")
    agregar("G09-L1-02", CLASE_9, "L1", "Bota humo azulado por el escape al arrancar por las mañanas.", "COTIDIANO", "arranque_frio", "humo_azul_manana", "", "", "SI", "NO", "", "L1 humo azul matutino.")
    agregar("G09-L1-03", CLASE_9, "L1", "Siento olor a aceite quemado cuando acelero en carretera.", "COTIDIANO", "carretera", "olor_aceite_quemado", "", "", "SI", "NO", "", "L1 olor a aceite quemado bajo carga.")
    agregar("G09-L1-04", CLASE_9, "L1", "La varilla marca el mínimo de aceite y no veo ninguna mancha en el piso.", "COTIDIANO", "reposo", "nivel_varilla_minimo_sin_mancha", "", "", "SI", "NO", "", "L1 baja de nivel sin fuga externa.")
    agregar("G09-L1-05", CLASE_9, "L1", "Al acelerar fuerte el auto deja una nube medio azul atrás.", "WHATSAPP", "aceleracion_fuerte", "nube_azul_acelerar", "", "", "SI", "NO", "", "L1 nube azul al acelerar fuerte.")
    agregar("G09-L1-06", CLASE_9, "L1", "Tengo que andar con un cuarto de aceite en la maletera para rellenar.", "WHATSAPP", "rutina", "relleno_constante_aceite", "", "", "SI", "NO", "", "L1 hábito de relleno constante.")
    agregar("G09-L1-07", CLASE_9, "L1", "Sale humo por la tapa por donde se echa el aceite si la saco con el motor prendido.", "COTIDIANO", "ralenti", "humo_tapa_llenado_aceite", "", "", "SI", "NO", "", "L1 soplado por tapa de llenado (blow-by).")
    agregar("G09-L1-08", CLASE_9, "L1", "Las bujías salen negras y grasosas cada vez que las reviso.", "TALLER", "inspeccion_bujias", "bujias_carbon_grasoso", "", "", "SI", "NO", "", "L1 bujías empapadas en aceite quemado.")
    agregar("G09-L1-09", CLASE_9, "L1", "El motor consume aceite pero no gotea nada por abajo.", "COTIDIANO", "marcha", "consumo_aceite_sin_goteo", "", "", "SI", "NO", "", "L1 consumo interno sin goteo.")
    agregar("G09-L1-10", CLASE_9, "L1", "Consume aciete y bota humo azul cuando lo piso despues de una bajada.", "ERROR_ORTOGRAFICO", "desaceleracion_bajada", "humo_azul_post_bajada", "", "", "SI", "NO", "", "L1 humo tras retención con error ortográfico.")

    # --- L2 (15 casos) ---
    agregar("G09-L2-01", CLASE_9, "L2", "El auto bota una bocanada de humo azul en el primer arranque matutino que dura 10 segundos y luego desaparece, bajando medio litro de aceite al mes.", "TALLER", "arranque_frio", "bocanada_azul_arranque|consumo_medio_litro", "humo_continuo", "", "NO", "SI", CLASE_10, "L2 retenes de válvula en frío vs bomba de aceite.")
    agregar("G09-L2-02", CLASE_9, "L2", "Consume un litro de aceite cada 800 kilómetros botando humo azul constante en subidas y aceleraciones fuertes, sin manchas en el piso del garaje.", "COTIDIANO", "subida_aceleracion", "consumo_1l_800km|humo_azul_aceleracion", "manchas_piso", "", "NO", "SI", CLASE_10, "L2 desgaste de anillos bajo carga vs presión de bomba.")
    agregar("G09-L2-03", CLASE_9, "L2", "Al retirar la varilla con el motor encendido sopla vapor aceitoso continuo por el tubo y el escape deja hollín negro grasoso en el paragolpes.", "TECNICO", "ralenti", "blowby_tubo_varilla|hollin_grasoso_escape", "perdida_presion_aceite", "", "NO", "SI", CLASE_10, "L2 sobrepresión de cárter (blow-by) vs testigo de presión.")
    agregar("G09-L2-04", CLASE_9, "L2", "Hola, mi carro gasta un galón de aceite entre cambio y cambio. No gotea nada por el retén del cigüeñal y la presión de aceite está perfecta.", "WHATSAPP", "rutina", "gasto_aceite_elevado", "goteo_reten_ciguenal|baja_presion_aceite", "", "NO", "SI", CLASE_10, "L2 consumo con presión de aceite normal descarta bomba.")
    agregar("G09-L2-05", CLASE_9, "L2", "Después de bajar una cuesta larga con freno de motor, al pisar el acelerador a fondo sale una cortina de humo azul por el escape.", "COTIDIANO", "aceleracion_post_retencion", "humo_azul_retencion_vacio", "humo_negro", "", "NO", "NO", "", "L2 succión de aceite por retenes de válvula por alto vacío.")
    agregar("G09-L2-06", CLASE_9, "L2", "Las cuatro bujías presentan costra negra gruesa de carbón aceitoso y el motor consume un litro cada 1000 km sin pérdida de agua.", "TALLER", "inspeccion_bujias", "bujias_costra_aceite|consumo_1l_1000km", "perdida_refrigerante", "", "NO", "SI", CLASE_6, "L2 bujías empapadas sin consumo de agua descarta culata.")
    agregar("G09-L2-07", CLASE_9, "L2", "El motor consume aceite pero no tiene ninguna fuga externa visible. La luz del aceite nunca se prende y no suena ningún cascabeleo de taqués.", "COTIDIANO", "marcha", "consumo_aceite_sin_fuga", "testigo_aceite_encendido|ruido_taques", "", "NO", "SI", CLASE_10, "L2 ausencia de testigo y de ruido descarta bomba defectuosa.")
    agregar("G09-L2-08", CLASE_9, "L2", "Prueba de compresión en seco arrojó 120 psi parejos en los 4 cilindros, pero al agregar una cucharada de aceite subió a 160 psi.", "TECNICO", "prueba_compresion", "compresion_seco_120_humedo_160", "compresion_desigual", "", "NO", "NO", "", "L2 prueba húmeda confirma sellado de anillos.")
    agregar("G09-L2-09", CLASE_9, "L2", "Mi carro bota humo asul cada ves que salgo de un semáforo rápido y tengo que echarle aceite cada semana para que no baje del nivel.", "ERROR_ORTOGRAFICO", "salida_semaforo", "humo_azul_salida|relleno_semanal_aceite", "charco_cochera", "", "NO", "SI", CLASE_10, "L2 humo azul en aceleración con error ortográfico.")
    agregar("G09-L2-10", CLASE_9, "L2", "Humo azulado visible por el retrovisor al pasar los 3500 rpm en carretera abierta. El filtro de aire tiene residuos de aceite del respiradero PCV.", "TALLER", "alta_rpm", "humo_azul_3500rpm|aceite_en_filtro_pcv", "fuga_carter", "", "NO", "NO", "", "L2 blow-by satura sistema PCV en alta rotación.")
    agregar("G09-L2-11", CLASE_9, "L2", "Buenas, el carro tiene 280 mil km y se come un litro cada mil km. En frío humea azul y en caliente se calma un poco.", "WHATSAPP", "arranque_frio_vs_caliente", "consumo_1l_1000km_alto_km|humo_azul_frio", "fuga_reten", "", "NO", "NO", "", "L2 desgaste general por alto kilometraje.")
    agregar("G09-L2-12", CLASE_9, "L2", "El escape huele a aceite quemado penetrante y el catalizador empieza a taparse, arrojando código P0420 por contaminación de aceite.", "TECNICO", "marcha", "olor_aceite_quemado|dtc_p0420_catalizador_aceite", "misfire_encendido", "P0420", "NO", "SI", "Convertidor catalitico ineficiente u obstruido (DTC P0420 / P0430)", "L2 catalizador degradado por consumo crónico de aceite.")
    agregar("G09-L2-13", CLASE_9, "L2", "Se revisó cárter, tapa de balancines y retén de bancada sin detectar goteo; el consumo de litro y medio por cambio es puramente por combustión.", "TALLER", "inspeccion_fugas", "sin_fugas_carter_balancines_bancada|consumo_por_combustion", "goteo_reten", "", "NO", "SI", CLASE_10, "L2 inspección descarta fugas externas.")
    agregar("G09-L2-14", CLASE_9, "L2", "Al pisar el acelerador con el carro caliente tira humo azul grisáceo. La presión de aceite se midió en 40 psi a 2000 rpm estando en rango.", "TECNICO", "aceleracion_caliente", "humo_azul_grisaceo|presion_aceite_40psi_ok", "baja_presion_aceite", "", "NO", "SI", CLASE_10, "L2 presión 40 psi normal descarta falla de bomba.")
    agregar("G09-L2-15", CLASE_9, "L2", "El nivel de aceite baja de la marca FULL a LOW en 600 kilómetros de autopista con humo azul en retenciones y aceleradas bruscas.", "COTIDIANO", "autopista", "caida_full_a_low_600km|humo_azul_retencion", "fuga_externa", "", "NO", "NO", "", "L2 caída acelerada de nivel en autopista.")

    # --- L3 (15 casos) ---
    agregar("G09-L3-01", CLASE_9, "L3", "Consumo excesivo de 1.2 litros de aceite por cada 1000 km sin goteo externo. Prueba de compresión seca marcó 115-118 psi en los 4 cilindros; al inyectar 10 ml de aceite la compresión subió a 155-160 psi en todos, confirmando desgaste en los aros de compresión y rascadores.", "TECNICO", "prueba_compresion_humeda", "consumo_1_2l_1000km|compresion_seca_115_humeda_160", "fugas_externas", "", "NO", "SI", CLASE_10, "L3 prueba seca vs húmeda certifica anillos.")
    agregar("G09-L3-02", CLASE_9, "L3", "El vehículo emite densa humareda azulada durante los primeros 15 segundos tras el arranque en frío luego de estar parado toda la noche. Al calentar el humo cesa y la prueba de compresión arrojó 170 psi parejos, diagnosticándose desgaste en los retenes de guías de válvulas.", "TALLER", "arranque_frio_matutino", "humareda_azul_15seg_frio|compresion_170psi_buena", "humo_continuo_aceleracion", "", "NO", "SI", CLASE_6, "L3 retenes de válvula: humo matutino con compresión 170 psi.")
    agregar("G09-L3-03", CLASE_9, "L3", "Cliente reporta gasto de aceite de 1 litro cada 700 km con humo azul al acelerar a más de 3000 rpm. Inspección endoscópica en cilindros muestra paredes con rayaduras verticales y carbón aceitoso en corona de pistones. El testigo de presión de aceite permanece apagado.", "TECNICO", "endoscopia_cilindros", "rayaduras_cilindro_endoscopia|carbon_corona_piston", "testigo_presion_aceite", "", "NO", "SI", CLASE_10, "L3 endoscopía confirma rayado de cilindro con presión OK.")
    agregar("G09-L3-04", CLASE_9, "L3", "Humo azul constante en aceleraciones bajo carga. Se retiraron las 4 bujías encontrándose electrodos cubiertos de costra de ceniza blanca aceitosa. La prueba de vacío del cárter muestra sobrepresión positiva de 2 psi por paso de compresión a través de anillos desgastados.", "TALLER", "aceleracion_carga", "bujias_ceniza_aceite|presion_positiva_carter_2psi", "falla_bujias_combustible", "P0300", "NO", "SI", "Falla en bujias o bobinas de encendido (misfire)", "L3 sobrepresión positiva en cárter por anillos.")
    agregar("G09-L3-05", CLASE_9, "L3", "Hola, mi camioneta quema aceite en subidas botando humo azul por el escape. En 3000 km se tomó 4 litros. La revisaron abajo y no gotea una gota. Las bujías salen empapadas en aceite quemado y no pierde refrigerante.", "WHATSAPP", "subidas", "quema_aceite_humo_azul|consumo_4l_3000km|bujias_aceite", "goteo_externo|perdida_refrigerante", "", "NO", "SI", CLASE_6, "L3 alto consumo en subidas sin pérdida de refrigerante.")
    agregar("G09-L3-06", CLASE_9, "L3", "Vehículo con 240,000 km presenta humo azul al acelerar fuerte y en retención de motor. Presión de aceite medida con manómetro mecánico marca 42 psi a 2500 rpm descartando bomba defectuosa. La prueba de fuga de cilindros arrojó 25% de fuga hacia el cárter en cilindros 2 y 3.", "TECNICO", "prueba_fugas_cilindro", "fuga_25_porciento_a_carter|presion_aceite_42psi_ok", "baja_presion_bomba", "", "NO", "SI", CLASE_10, "L3 leakdown hacia cárter con presión 42 psi descarta bomba.")
    agregar("G09-L3-07", CLASE_9, "L3", "El motor consume aceite a razón de 1 litro cada 650 km. En desaceleración prolongada desde 80 km/h y posterior acelerada a fondo genera una densa nube azul. Retenes de válvulas endurecidos y cristalizados por sobrecalentamiento previo.", "TALLER", "prueba_desaceleracion_aceleracion", "nube_azul_post_desaceleracion|consumo_1l_650km", "perdida_presion", "", "NO", "NO", "", "L3 retención prolongada succiona aceite por retenes cristalizados.")
    agregar("G09-L3-08", CLASE_9, "L3", "DTC P0420 por ineficiencia de catalizador. El sensor de oxígeno posterior reporta lectura contaminada por hollín de aceite. El motor consume 1.5 cuartos de aceite cada 1000 km y genera humo azulado al acelerar en caliente sin goteo en cárter.", "TECNICO", "motor_caliente", "dtc_p0420|sensor_oxigeno_hollin_aceite|consumo_1_5qt", "fuga_carter", "P0420", "NO", "SI", "Convertidor catalitico ineficiente u obstruido (DTC P0420 / P0430)", "L3 DTC P0420 secundario a quema crónica de aceite.")
    agregar("G09-L3-09", CLASE_9, "L3", "Mi carro gasta un litro de aceite cada 500 km y bota humo azul al acelerar. El manómetro marca 35 psi de presion de aceite en caliente, o sea la bomba esta buena pero los anillos ya no sellan y pasan aceite a la camara.", "ERROR_ORTOGRAFICO", "aceleracion_caliente", "gasto_1l_500km|humo_azul|presion_35psi_ok", "falla_bomba_aceite", "", "NO", "SI", CLASE_10, "L3 presión 35 psi confirma aros y descarta bomba con ortografía informal.")
    agregar("G09-L3-10", CLASE_9, "L3", "Inspección de bujías revela depósito vitrificado de aceite quemado en cilindros 1 y 4. Prueba de compresión húmeda confirmó recuperación de 45 psi por cilindro tras sellar aros. Nivel de refrigerante permanece intacto sin mezcla de fluidos.", "TALLER", "taller_bujias", "bujias_deposito_vitrificado|recuperacion_45psi_humeda", "perdida_refrigerante|emulsion", "", "NO", "SI", CLASE_6, "L3 diagnóstico formal de aros sin daño a culata.")
    agregar("G09-L3-11", CLASE_9, "L3", "El cliente debe agregar 1 litro de aceite 20W-50 cada 800 km para mantener la varilla en nivel. Al desacelerar en bajada y acelerar produce humo azul notorio. Válvula PCV nueva no corrigió el problema comprobándose sellos de válvulas gastados.", "COTIDIANO", "bajada_y_aceleracion", "consumo_1l_800km_aceite_grueso|humo_azul", "falla_valvula_pcv", "", "NO", "NO", "", "L3 PCV nueva no resuelve consumo por sellos de válvula.")
    agregar("G09-L3-12", CLASE_9, "L3", "Prueba de hermeticidad con detector de fugas: cilindro 1 fuga 28% con soplido audible a través de la boca de llenado de aceite en la tapa de balancines. No hay soplido hacia el radiador ni hacia el múltiple de escape.", "TECNICO", "prueba_hermeticidad", "fuga_28_porciento_hacia_tapa_balancines", "fuga_hacia_radiador|fuga_escape", "", "NO", "SI", CLASE_6, "L3 fuga audible hacia tapa de balancines descarta culata y escape.")
    agregar("G09-L3-13", CLASE_9, "L3", "El auto consume aceite de manera sostenida a razón de 1 litro cada 1000 km. La compresión en seco marcó 125 psi y la húmeda 165 psi. En aceleraciones fuertes en segunda y tercera marcha el tubo de escape suelta humo azul sin pérdida de potencia severa.", "TALLER", "segunda_tercera_marcha", "consumo_1l_1000km|seco_125_humedo_165|humo_azul", "falla_encendido", "", "NO", "SI", "Falla en bujias o bobinas de encendido (misfire)", "L3 aros de compresión con humo azul en marchas cortas.")
